import numpy as np
ys,xs=np.nonzero(G)
pts=set(zip(ys.tolist(),xs.tolist()))
# connected components (8-conn)
seen=set(); comps=[]
for p in pts:
    if p in seen: continue
    stack=[p]; comp=set()
    while stack:
        q=stack.pop()
        if q in seen: continue
        seen.add(q); comp.add(q)
        for dy in(-1,0,1):
            for dx in(-1,0,1):
                n=(q[0]+dy,q[1]+dx)
                if n in pts and n not in seen: stack.append(n)
    comps.append(comp)
for c in sorted(comps,key=len,reverse=True):
    ys2=[p[0] for p in c]; xs2=[p[1] for p in c]
    print(len(c), min(ys2),max(ys2),min(xs2),max(xs2))
    for r in range(min(ys2),max(ys2)+1):
        print(''.join(str(G[r][c]) if (r,c) in c else '.' for c in range(min(xs2),max(xs2)+1)))
    print()

